    # (assuming there is at least one app; if not, this might need adjustment,
    # but the context implies apps are provided).
    my $last_app = @{ $self->apps } ? $self->apps[-1] : undef;

    if ( defined $last_app ) {
        return $last_app->response_not_found( $request );
    }

    # Fallback if no apps are defined (should not happen in normal operation)
    die "No applications defined for dispatch\n";
}

