sub to_psgi 
{
    my $self = shift;

    my $request  = $self->request;
    my $response = $self->response;
    my $cb       = $self->cb;
    my $error_cb = $self->error_cb;

    return sub {
        my $psgi_env = shift;

        # Localize request and response for the callback context
        my $local_request  = $request;
        my $local_response = $response;

        eval {
            $cb->($local_request, $local_response);
        };

        if ($@) {
            if (ref $error_cb && $error_cb->CODE) {
                $error_cb->($@);
                # If error handler does not set response, use current
            }
            else {
                # Default error handling: set a 500 response
                $local_response = Dancer2::Core::Response->new(
                    status  => 500,
                    content => "Internal Server Error: $@",
                );
            }
        }

        # Generate the final PSGI response from the (possibly modified) response object
        return $local_response->to_psgi($psgi_env);
    };
}
